    private final void updateShapeModifiers(float pSecondsElapsed) {
        ArrayList<IShapeModifier> shapeModifiers = this.mShapeModifiers;
        int shapeModifierCount = this.mShapeModifierCount;
        if (shapeModifierCount > 0) {
            for (int i = shapeModifierCount - 1; i >= 0; i--) {
                IShapeModifier shapeModifier = shapeModifiers.get(i);
                shapeModifier.onUpdateShape(pSecondsElapsed, this);
                if (shapeModifier.isFinished() && shapeModifier.isRemoveWhenFinished()) {
                    this.mShapeModifierCount--;
                    shapeModifiers.remove(i);
                }
            }
        }
    }

