        this.mMore = new TextSprite(0.5f * this.mGameWidth, this.mSubmit.getY(), "更多游戏", 2, this.mGame.mTypeface, size);
        this.mRetry = new TextSprite(0.75f * this.mGameWidth, this.mSubmit.getY(), "重新开始", 2, this.mGame.mTypeface, size);
        this.mSubmit.setUnderline(true);
        this.mMore.setUnderline(true);
        this.mRetry.setUnderline(true);
        addEntity(0, this.mDistance, this.mBest, this.mSubmit, this.mMore, this.mRetry);
    }

    @Override // com.andoop.android.engine.Scene
    public void onReady() {
        super.onReady();
        this.mGame.showAd();
        long current = System.currentTimeMillis();
        if (current - this.mGame.lastAdShown > MY_AD_REFRESH_INTERVAL) {
            this.mGame.lastAdShown = current;
            if (this.mGame.adview != null) {
                this.mGame.adview.requestFreshAd();
            }
        }
    }

    @Override // com.andoop.android.engine.Scene
    public boolean onTouch(float x, float y, MotionEvent e) {
        if (this.mRetry.onClick(x, y, e)) {
            this.mGame.playPress();
            this.mGame.setScene(this.mGame.mGameScene);
            return true;
        }
        if (this.mMore.onClick(x, y, e)) {
            this.mGame.playPress();
            Game game = this.mGame;
            this.mGame.getClass();
            game.showDialog(1);
            return true;
        }
        if (!this.mSubmit.onClick(x, y, e)) {
            return true;
        }
        this.mGame.playPress();
        submitScore();
        return true;
    }

    void submitScore() {
        HighScoreActivity.submitHighScore(this.mGame, this.mDistanceInt, this.mGame.mMenuScene, this.mGame.getResources().getString(R.string.highscore_url));
    }

    void setDistance(int now, int bestLast) {
        this.mDistance.setText("得分: " + now);
        this.mBest.setText("最高分: " + bestLast);
        this.mDistanceInt = now;
    }
}

