    class Android2ButtonHandler {
        MotionEvent mEventDown;
        MotionEvent mEventPointer1Down;
        MotionEvent mEventPointer2Down;

        Android2ButtonHandler() {
        }

        public boolean onTouch(float x, float y, MotionEvent e) {
            int action = e.getAction();
            if (action == 0) {
                this.mEventDown = e;
                return true;
            }
            if (action == 5) {
                this.mEventPointer1Down = e;
                return true;
            }
            if (action == 261) {
                this.mEventPointer2Down = e;
                return true;
            }
            return true;
        }

        public void handlerTouchEvent() {
            if (this.mEventDown != null) {
                long time = this.mEventDown.getEventTime();
                long now = SystemClock.uptimeMillis();
                if (now - time > 25) {
                    if (this.mEventPointer2Down == null) {
                        GameScene.this.handleButtonPress(this.mEventDown.getX(), this.mEventDown.getY());
                    } else {
                        float p1 = this.mEventDown.getPressure();
                        float p2 = this.mEventPointer2Down.getPressure();
                        if (p1 > p2) {
                            GameScene.this.handleButtonPress(this.mEventDown.getX(), this.mEventDown.getY());
                        } else {
                            GameScene.this.handleButtonPress(this.mEventPointer2Down.getX(1), this.mEventPointer2Down.getY(1));
                        }
                    }
                    this.mEventDown = null;
                    this.mEventPointer2Down = null;
                    return;
                }
                return;
            }
            if (this.mEventPointer2Down != null) {
                GameScene.this.handleButtonPress(this.mEventPointer2Down.getX(1), this.mEventPointer2Down.getY(1));
                this.mEventPointer2Down = null;
            } else if (this.mEventPointer1Down != null) {
                GameScene.this.handleButtonPress(this.mEventPointer1Down.getX(0), this.mEventPointer1Down.getY(0));
                this.mEventPointer1Down = null;
            }
        }
    }
}

